import {createHash} from 'node:crypto';
export function registrationFingerprint(input:Record<string,unknown>) {
  const canonical=(value:any):any=>Array.isArray(value)?value.map(canonical):value&&typeof value==='object'?Object.fromEntries(Object.keys(value).sort().map(k=>[k,canonical(value[k])])):value;
  // submittedAt is generated by the form, not an answer or a user-selected occurrence time.
  const {submissionId,submittedAt,...answers}=input;
  return createHash('sha256').update(JSON.stringify(canonical(answers))).digest('hex');
}
export function registrationSubmissionId(input:Record<string,unknown>) {
  if(input.submissionId===undefined)return 'legacy_'+registrationFingerprint(input);
  if(typeof input.submissionId!=='string'||!/^[A-Za-z0-9_-]{16,100}$/.test(input.submissionId))throw Object.assign(Error('Invalid registration submission ID'),{status:400});
  return input.submissionId;
}
export const registrationReceiptKey=(visitorId:string,submissionId:string)=>createHash('sha256').update(JSON.stringify([visitorId,submissionId])).digest('hex');
export function publicRegistrationProfile(profile:any) {
  const fields=['id','name','fullName','currentStatus','goal','goals','city','cityDetail','whatsapp','email','mode','reportedLevel','levelState','language','submittedAt','parentContact','buyingSignal','buyingSignals'];
  return Object.fromEntries(fields.filter(k=>profile[k]!==undefined).map(k=>[k,profile[k]]));
}
